#!/usr/bin/env python3
import json
import re
from docx import Document

# Load employee data
with open('/root/employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template
doc = Document('/root/offer_letter_template.docx')

def replace_placeholders_in_text(text, data):
    """Replace all {{PLACEHOLDER}} with corresponding values from data."""
    for key, value in data.items():
        placeholder = f'{{{{{key}}}}}'
        text = text.replace(placeholder, str(value))
    return text

def process_relocation_condition(text, include_relocation):
    """Handle {{IF_RELOCATION}}...{{END_IF_RELOCATION}} blocks."""
    if include_relocation:
        # Keep content but remove markers
        text = text.replace('{{IF_RELOCATION}}', '')
        text = text.replace('{{END_IF_RELOCATION}}', '')
    else:
        # Remove the entire block including content
        pattern = r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}'
        text = re.sub(pattern, '', text, flags=re.DOTALL)
    return text

include_relocation = data.get('RELOCATION_PACKAGE', '').lower() == 'yes'

# Process paragraphs
for paragraph in doc.paragraphs:
    full_text = paragraph.text
    if '{{IF_RELOCATION}}' in full_text or '{{END_IF_RELOCATION}}' in full_text:
        full_text = process_relocation_condition(full_text, include_relocation)
    full_text = replace_placeholders_in_text(full_text, data)

    # Only update if changed
    if full_text != paragraph.text:
        # Preserve formatting by updating runs
        if paragraph.runs:
            # Clear all runs except first, put all text in first run
            for i, run in enumerate(paragraph.runs):
                if i == 0:
                    run.text = full_text
                else:
                    run.text = ''
        else:
            paragraph.text = full_text

# Process tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                full_text = paragraph.text
                if '{{IF_RELOCATION}}' in full_text or '{{END_IF_RELOCATION}}' in full_text:
                    full_text = process_relocation_condition(full_text, include_relocation)
                full_text = replace_placeholders_in_text(full_text, data)

                if full_text != paragraph.text:
                    if paragraph.runs:
                        for i, run in enumerate(paragraph.runs):
                            if i == 0:
                                run.text = full_text
                            else:
                                run.text = ''
                    else:
                        paragraph.text = full_text

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print("Offer letter saved to /root/offer_letter_filled.docx")

